import pytest
from jinja2 import Environment
from jinja2 import DictLoader
from jinja2 import TemplateSyntaxError
from jinja2.ext import InternationalizationExtension


class TestI18nBlockPGettext:
    def test_block_pgettext(self):
        env = Environment(
            extensions=[InternationalizationExtension],
            loader=DictLoader(
                {
                    "test.html": """
                        {% pgettext "context" %}Hello{% endpgettext %}
                        {% pgettext "another_context" %}World{% endpgettext %}
                    """
                }
            ),
        )
        env.install_gettext_callables(
            lambda s: s, lambda s, p, n: s if n == 1 else p, newstyle=True
        )

        # This test asserts that the template can be parsed without syntax errors.
        # The actual translation behavior is handled by the installed gettext callables,
        # which are mocked here to simply return the input string.
        # The bug is that the parser does not recognize `pgettext` as a block.
        template = env.get_template("test.html")
        assert template.render().strip() == "Hello World"

    def test_block_pgettext_with_variables(self):
        env = Environment(
            extensions=[InternationalizationExtension],
            loader=DictLoader(
                {
                    "test.html": """
                        {% pgettext "context" name=user_name %}Hello %(name)s{% endpgettext %}
                    """
                }
            ),
        )
        env.install_gettext_callables(
            lambda s: s, lambda s, p, n: s if n == 1 else p, newstyle=True
        )

        template = env.get_template("test.html")
        assert template.render(user_name="John").strip() == "Hello John"

    def test_block_pgettext_with_pluralize(self):
        env = Environment(
            extensions=[InternationalizationExtension],
            loader=DictLoader(
                {
                    "test.html": """
                        {% pgettext "context" num=count %}One item{% pluralize %}{{ num }} items{% endpgettext %}
                    """
                }
            ),
        )

        def _pgettext_mock(context, singular, plural, n):
            if n == 1:
                return singular
            return plural

        env.install_gettext_callables(
            lambda s: s, _pgettext_mock, newstyle=True,
        )

        template = env.get_template("test.html")
        assert template.render(count=1).strip() == "One item"
        assert template.render(count=5).strip() == "5 items"

